-- belueftungsart
update public.fields set verification_status='verified_against_standard', verification_quote='Die Aufgabe von Belüftungssystemen ist es, den für den Stoffwechsel der aeroben Mikroorganismen benötigten Sauerstoff in das Belebungsbecken einzutragen. Dazu werden Druckbelüftungs- und Oberflächenbelüftungssysteme eingesetzt. | Sondersysteme sind häufig dadurch gekennzeichnet, dass sie auf einzelne Komponenten verzichten, mehrere Aufgaben gleichzeitig ausführen und/oder besondere Betriebseigenschaften besitzen. — printed p.23, 30', verification_note='md-verified 2026-09-07 (§4.1.1, §4.1.4.1, printed p.23, 30) [VC]', verified_at=now() where id='4c6742a3-1f25-4962-898c-c80dbba420be' and verification_status not in ('verified_against_standard','corrected');
-- sondersystem_typ
