update public.fields set verification_status='verified_against_standard', verification_quote='I Lastfall 3: Minimaler Sauerstoffbedarf im Ist-Zustand, $O V_{\mathrm{h}, \min }$ | Der minimale Sauerstoffbedarf auf Anlagen ohne einen signifikanten, auch in den Nachtstunden zufließenden Frachtanteil ergibt sich vereinfacht über den Ansatz der endogenen Atmung nach Arbeitsblatt DWA-A 131:2016 Gleichung (63): | O V_{\mathrm{h}, \min }=\frac{O V_{\mathrm{d}, \mathrm{C}, \mathrm{aM}}}{\left(\frac{3,92}{t_{\mathrm{TS}} \cdot 1,072^{\left(T_{\mathrm{w}}-15\right)}}+1,66\right) \cdot 24} \quad\left(\mathrm{~kg} / \mathrm{h} \mathrm{O}_{2}\right) \tag{16} | mit $T_{\mathrm{W}}$ als der Temperatur im Jahresmittel sowie mit $t_{\mathrm{TS}}$ als dem für diesen Lastfall ermittelten Schlammalter. — printed p.35', verification_note='md-verified 2026-09-07 (§4.3.1 Gl. (16), printed p.35) [VC]', verified_at=now() where id='4e0c1103-7d6b-4835-a3ad-c75ba62d462e' and verification_status not in ('verified_against_standard','corrected');
