-- OV_h
update public.fields set verification_status='verified_against_standard', verification_quote='Die Auslegung von Druckluftbelüftungssystemen geht von dem für die einzelnen Lastfälle ermittelten Sauerstoffbedarf aus. Hieraus wird die notwendige Sauerstoffzufuhr SOTR als maßgebliche Dimensionierungsgröße für die Bemessung der Belüftung ermittelt. | \text { SOTR }=\frac{f_{\mathrm{d}} \cdot C_{\mathrm{S}, 20}}{\alpha \cdot\left(f_{\mathrm{d}} \cdot C_{\mathrm{S}, \mathrm{~T}}-C_{\mathrm{x}}\right) \cdot \theta^{\left(T_{\mathrm{W}}-20\right)}} \cdot O V_{\mathrm{h}} \quad\left(\mathrm{~kg} / \mathrm{h} \mathrm{O}_{2}\right) \tag{20} — printed p.36', verification_note='md-verified 2026-09-07 (§4.3.2 Gl. (20), printed p.36) [VC]', verified_at=now() where id='fd73e22c-4fc4-497d-aee2-58d8629f10bf' and verification_status not in ('verified_against_standard','corrected');
