-- h_BB
update public.fields set verification_status='verified_against_standard', verification_quote='3.3 Abkürzungen und Symbole | \hline $h_{\text {BB }}$ & m & Wassertiefe \\ | Die bisherigen Erfahrungswerte sind allerdings auf Wassertiefen bis $h_{\mathrm{BB}}=20 \mathrm{~m}$ beschränkt. — printed p.16-22, 10', verification_note='md-verified 2026-09-07 (§3.3, §1, printed p.16-22, 10) [VC]', verified_at=now() where id='0f61150a-9b70-48fc-befa-b07c6d0fccbb' and verification_status not in ('verified_against_standard','corrected');
-- h_D
update public.fields set verification_status='verified_against_standard', verification_quote='Die Einblastiefe ( $h_{\mathrm{D}}$ ) ist definiert als Abstand zwischen der Oberkante des Belüftungselements und der Wasseroberfläche im Ruhezustand. Übliche Einblastiefen sind zwischen 4 m bis 6 m . In Sonderfällen wurden in kommunalen Kläranlagen auch erheblich größere Einblastiefen von bis zu 17 m realisiert. — printed p.31', verification_note='md-verified 2026-09-07 (§4.2.2, printed p.31) [VC]', verified_at=now() where id='d75c91b0-1df9-40f0-acbd-6650c5afaa96' and verification_status not in ('verified_against_standard','corrected');
-- ET
update public.fields set verification_status='verified_against_standard', verification_quote='Bei den Oberflächenbelüftern bezeichnet die Eintauchtiefe die Tiefe ( m ), die das Aggregat von der Oberfläche aus in das Wasser eintaucht. Bei Walzenbelüftern beträgt diese Tiefe maximal $0,3 \mathrm{~m}$, bei Kreiselbelüftern ca. $0,5 \mathrm{~m}$. | Die Eintauchtiefe von Walzenbelüftern sollte zur Vermeidung stehender Wellen bei etwa $0,25 \mathrm{~m}$ bis $0,3 \mathrm{~m}$ liegen. In diesem Bereich kann auch von einem Optimum in Bezug auf den Sauerstoffertrag ausgegangen werden. Bei Kreiselbelüftern sollte die Eintauchtiefe einen Wert von $0,5 \mathrm{~m}$ nicht überschreiten. — printed p.31, 41', verification_note='md-verified 2026-09-07 (§4.2.2, §4.3.3, printed p.31, 41) [VC]', verified_at=now() where id='7f42cc53-edc2-4dfb-b745-0c5304a60bf0' and verification_status not in ('verified_against_standard','corrected');
