-- q_L_Bel
update public.fields set verification_status='verified_against_standard', verification_quote='3.3 Abkürzungen und Symbole | \hline $q_{\llcorner, \text {Bel }}$ & $\mathrm{m}_{\mathrm{N}}^{3} /(\mathrm{St} \cdot \mathrm{h})$ & Luftbeaufschlagung, spezifischer Luftvolumenstrom je Belüfterelement \\ | Die Luftbeaufschlagung bzw. der Luftvolumenstrom ( $Q_{L, N}$ ) wird oft spezifisch angegeben: beispielsweise bezogen auf das Belebungsbeckenvolumen ( $q_{\llcorner, \mathrm{BB}}$ ), auf die Länge der Belüftungselemente ( $q_{\mathrm{L}, \mathrm{Bel}}$ in $\mathrm{m}_{\mathrm{N}}^{3} /(\mathrm{m} \cdot \mathrm{h})$ ), auf die abgasende Fläche der Belüftungselemente ( $q_{\mathrm{L}, \text { Bel }}$ in $\mathrm{m}_{\mathrm{N}}^{3} /\left(\mathrm{m}^{2} \cdot \mathrm{~h}\right)$ ) oder auf die Anzahl der Belüftungselemente ( $q_{\llcorner, \text {Bel }}$ in $\mathrm{m}_{\mathrm{N}}^{3} /(\mathrm{St} \cdot \mathrm{h})$ ). — printed p.16-22, 32', verification_note='md-verified 2026-09-07 (§3.3, §4.2.4, printed p.16-22, 32) [VC]', verified_at=now() where id='57f41a9d-09c5-45c8-b608-55e296121ede' and verification_status not in ('verified_against_standard','corrected');
-- q_L_Bel_erf
