-- alpha
update public.fields set verification_status='verified_against_standard', verification_quote='Der $\alpha$-Wert ist ein empirischer Faktor, der als Verhältnis der Belüftungskoeffizienten unter Betriebsund Reinwasserbedingungen definiert ist: | \alpha=\frac{k_{\mathrm{L}} a_{20} \text { in belebtem Schlamm }}{k_{\mathrm{L}} a_{20} \text { in Reinwasser }} \tag{8} — printed p.14', verification_note='md-verified 2026-09-07 (§3.2.8 Gl. (8), printed p.14) [VC]', verified_at=now() where id='33cfc56e-36f3-47e4-af66-09376be17b61' and verification_status not in ('verified_against_standard','corrected');
-- kLa20_aS
update public.fields set verification_status='verified_against_standard', verification_quote='Der $\alpha$-Wert ist ein empirischer Faktor, der als Verhältnis der Belüftungskoeffizienten unter Betriebsund Reinwasserbedingungen definiert ist: | \alpha=\frac{k_{\mathrm{L}} a_{20} \text { in belebtem Schlamm }}{k_{\mathrm{L}} a_{20} \text { in Reinwasser }} \tag{8} | Beide $k_{\llcorner } a_{20}$-Werte müssen dabei im gleichen Becken mit der gleichen Belüftungseinrichtung und mit gleicher Belüftungsintensität bestimmt werden, weil $\alpha$ nicht nur von der Abwasserbeschaffenheit, sondern in stärkerem Maße vom Belüftungssystem abhängt. — printed p.14', verification_note='md-verified 2026-09-07 (§3.2.8 Gl. (8), printed p.14) [VC]', verified_at=now() where id='98739d82-c9fd-45c0-84cc-d277f25dd09e' and verification_status not in ('verified_against_standard','corrected');
-- kLa20_RW
update public.fields set verification_status='verified_against_standard', verification_quote='\alpha=\frac{k_{\mathrm{L}} a_{20} \text { in belebtem Schlamm }}{k_{\mathrm{L}} a_{20} \text { in Reinwasser }} \tag{8} | Beide $k_{\llcorner } a_{20}$-Werte müssen dabei im gleichen Becken mit der gleichen Belüftungseinrichtung und mit gleicher Belüftungsintensität bestimmt werden, weil $\alpha$ nicht nur von der Abwasserbeschaffenheit, sondern in stärkerem Maße vom Belüftungssystem abhängt. — printed p.14', verification_note='md-verified 2026-09-07 (§3.2.8 Gl. (8), printed p.14) [VC]', verified_at=now() where id='a70430a7-4a62-4809-a699-db96bc0aa6e1' and verification_status not in ('verified_against_standard','corrected');
