-- kLaT
update public.fields set verification_status='verified_against_standard', verification_quote='3.3 Abkürzungen und Symbole | \hline $k_{\mathrm{L}} a_{\mathrm{T}}$ & $\mathrm{h}^{-1}$ & Belüftungskoeffizient für Reinwasser bei $T\left({ }^{\circ} \mathrm{C}\right)$ \\ — printed p.16-22', verification_note='md-verified 2026-09-07 (§3.3, printed p.16-22) [VC]', verified_at=now() where id='45901836-8fb8-4411-82ff-c36ca14257db' and verification_status not in ('verified_against_standard','corrected');
-- kLa20
update public.fields set verification_status='verified_against_standard', verification_quote='Der Belüftungskoeffizient $k_{\mathrm{L}} a_{\mathrm{T}}$ in $\mathrm{h}^{-1}$ (bzw. $1 / \mathrm{h}$ ) ist der Kennwert für die in einem bestimmten Becken auf eine bestimmte Leistung eingestellte Belüftungseinrichtung. Er wird aus dem Sauerstoffzufuhrversuch bei der Wassertemperatur im Belebungsbecken $T_{\mathrm{W}}\left({ }^{\circ} \mathrm{C}\right)$ errechnet. Bei gleicher Belüftungseinstellung steigt $k_{\mathrm{L}} a_{\mathrm{T}}$ (bzw. $\alpha k_{\mathrm{L}} a_{\mathrm{T}}$ ) mit steigender Temperatur. Es gilt nach DIN EN 12255-15:2004: | k_{\mathrm{L}} a_{20}=k_{\mathrm{L}} a_{\mathrm{T}} \cdot 1,024^{\left(20-T_{\mathrm{W}}\right)} \tag{7} — printed p.14', verification_note='md-verified 2026-09-07 (§3.2.7 Gl. (7), printed p.14) [VC]', verified_at=now() where id='f0be663f-8008-4922-84b2-7b9782ae48a1' and verification_status not in ('verified_against_standard','corrected');
-- theta
update public.fields set verification_status='verified_against_standard', verification_quote='3.3 Abkürzungen und Symbole | \hline $\theta$ & - & Temperaturkorrekturfaktor: 1,024 \\ | In diesem Bereich kann bei der Umrechnung des Belüftungskoeffizienten $k_{\llcorner } a_{\top}$ auf den Standardwert $k_{\llcorner } a_{20}$ der in allen national und international maßgebenden Messanleitungen aufgeführte Temperaturkorrekturfaktor $\theta=1,024$ angewendet werden. — printed p.16-22, 14', verification_note='md-verified 2026-09-07 (§3.3, §3.2.7, printed p.16-22, 14) [VC]', verified_at=now() where id='ebf38073-1ffd-46f4-a4ef-799e0944e39f' and verification_status not in ('verified_against_standard','corrected');
