update public.fields set verification_status='verified_against_standard', verification_quote='3.3 Abkürzungen und Symbole | \hline $S_{\text {TDS }, \alpha}$ & g/l & Salzgehalt unter Betriebsbedingungen (Abdampfrückstand gemäß DIN 38409 H1:1989) \\ — printed p.16-22', verification_note='md-verified 2026-09-07 (§3.3, printed p.16-22) [VC]', verified_at=now() where id='cbec95ef-0192-40ce-bcaf-b50a91446459' and verification_status not in ('verified_against_standard','corrected');
-- beta_St
update public.fields set verification_status='verified_against_standard', verification_quote='Für die Bemessung von Belüftungssystemen ist es zudem erforderlich, den Salzgehalt der Betriebsbedingungen auf den Salzgehalt unter Reinwasserbedingungen umzurechnen. Es gilt dann in Abhängigkeit des Gesamtgehalts an Salzen in Reinwasser, $S_{\text {TDS }, \mathrm{St}}(\mathrm{g} / \mathrm{l})$ : | \beta_{\mathrm{St}}=1,00-0,01 \cdot \mathrm{~S}_{\mathrm{TDS}, \mathrm{St}} \tag{-} — printed p.15', verification_note='md-verified 2026-09-07 (§3.2.11, printed p.15) [VC]', verified_at=now() where id='0bc2bd23-4832-48ec-9f59-758e29142b0c' and verification_status not in ('verified_against_standard','corrected');
-- beta_alpha
update public.fields set verification_status='verified_against_standard', verification_quote='In kommunalen Abwässern geht der $\beta_{\alpha}$-Wert gegen 1,0 und ist deshalb vernachlässigbar. Überschlägig kann man für kommunale Abwässer mit erheblichem Meerwasseranteil oder industrielle Abwässer den $\beta_{\alpha}$-Wert mithilfe des Gesamtgehalts an Salzen in Abwasser, $S_{\text {TDS }, \alpha}$ (g/l), berechnen (Merkblatt DWA-M 209:2007): | \beta_{\alpha}=1,00-0,01 \cdot S_{\mathrm{TDS}, \alpha} — printed p.15', verification_note='md-verified 2026-09-07 (§3.2.11, printed p.15) [VC]', verified_at=now() where id='1b790628-ffbb-421e-98dc-af8c88191708' and verification_status not in ('verified_against_standard','corrected');
-- f_S_St
update public.fields set verification_status='verified_against_standard', verification_quote='Für die Bemessung von Belüftungssystemen ist es zudem erforderlich, den Salzgehalt der Betriebsbedingungen auf den Salzgehalt unter Reinwasserbedingungen umzurechnen. Es gilt dann in Abhängigkeit des Gesamtgehalts an Salzen in Reinwasser, $\mathrm{S}_{\text {TDS }, \mathrm{St}}(\mathrm{g} / \mathrm{I})$ : | f_{\mathrm{S}, \mathrm{St}}=1,00+0,08 \cdot \mathrm{~S}_{\mathrm{TDS}, \mathrm{St}} \tag{13} — printed p.15', verification_note='md-verified 2026-09-07 (§3.2.12 Gl. (13), printed p.15) [VC]', verified_at=now() where id='5f7a4ecc-9e33-4bad-a065-f61ffb127c77' and verification_status not in ('verified_against_standard','corrected');
-- f_S_alpha
update public.fields set verification_status='verified_against_standard', verification_quote='In kommunalem Abwasser mit geringen Salzgehalten ist der $f_{\mathrm{S}, \alpha}$ von untergeordneter Bedeutung und geht gegen 1,0. Ansonsten gilt: | f_{\mathrm{S}, \alpha}=1,00+0,08 \cdot \mathrm{~S}_{\mathrm{TDS}, \alpha} \tag{-} | Die Gleichungen besitzen bis zu Salzgehalten von $10 \mathrm{~g} / \mathrm{l} \mathrm{Gültigkeit}$. Bei höheren Konzentrationen tritt bei feinblasigen Druckbelüftungssystemen keine weitere Verbesserung des Belüftungskoeffizienten auf. Hier $\operatorname{sind} f_{\mathrm{S}, \alpha}$ und $f_{\mathrm{S}, \mathrm{St}}$ dann mit 1,8 anzusetzen. — printed p.15', verification_note='md-verified 2026-09-07 (§3.2.12, printed p.15) [VC]', verified_at=now() where id='c86cb35f-8f83-4047-8c81-78dd63f2f580' and verification_status not in ('verified_against_standard','corrected');
