-- C_S_T
update public.fields set verification_status='verified_against_standard', verification_quote='3.3 Abkürzungen und Symbole | \hline $C_{\mathrm{S}, \mathrm{T}}$ & mg/l & Sauerstoffsättigungskonzentration bei $T_{\mathrm{W}}\left({ }^{\circ} \mathrm{C}\right)$ : $$ \frac{2.234,34}{\left(T_{\mathrm{w}}+45,93\right)^{1,31403}} $$ \\ — printed p.16-22', verification_note='md-verified 2026-09-07 (§3.3, printed p.16-22) [VC]', verified_at=now() where id='1de151c9-ee46-455e-aa6e-c73b7b5bad7a' and verification_status not in ('verified_against_standard','corrected');
-- C_S_St_T
update public.fields set verification_status='verified_against_standard', verification_quote='Der Standard-Sauerstoffsättigungswert $C_{S, S, T}$ in $\mathrm{mg} / \mathrm{l}$ stellt sich in Wasser bei konstanter und gleicher Temperatur von Wasser, wassergesättigter Luft bei einem Druck von 1.013 hPa und einem Salzgehalt $S_{\text {TDS,St }}$ von $0 \mathrm{mg} / \mathrm{l}$ ein. Standard-Sättigungswerte sind in DIN EN ISO 5814 tabelliert. — printed p.12', verification_note='md-verified 2026-09-07 (§3.2.1, printed p.12) [VC]', verified_at=now() where id='d1a69854-ac55-4de8-88c3-269cba3d6ede' and verification_status not in ('verified_against_standard','corrected');
-- C_x
update public.fields set verification_status='verified_against_standard', verification_quote='3.3 Abkürzungen und Symbole | \hline $C_{x}$ & mg/l & Sauerstoffkonzentration im Belebungsbecken \\ | Weiterhin kann es zweckmäßig sein, bei nur kurzzeitigen Belastungen den erforderlichen Sauerstoffgehalt im Becken ( $C_{\mathrm{x}}$ ) schon bei der Bemessung von üblicherweise $2 \mathrm{mg} / \mathrm{l}$ auf bis zu $1 \mathrm{mg} / \mathrm{l}$ zu reduzieren. — printed p.16-22, 34', verification_note='md-verified 2026-09-07 (§3.3, §4.3.1, printed p.16-22, 34) [VC]', verified_at=now() where id='64e3014d-02bd-4122-8b14-c659f754bcad' and verification_status not in ('verified_against_standard','corrected');

-- ---------------------------------------------------------------- M2291-04
-- n_Bel
update public.fields set verification_status='verified_against_standard', verification_quote='3.3 Abkürzungen und Symbole | \hline $n_{\text {Bel }}$ & - & Anzahl der Belüfterelemente \\ | Die Berechnung der Anzahl der Belüftungselemente erfolgt im Rahmen der Entwurfsplanung über die herstellerspezifische, empfohlene Beaufschlagung für einen energetisch wirtschaftlichen Betrieb. — printed p.16-22, 40', verification_note='md-verified 2026-09-07 (§3.3, §4.3.2, printed p.16-22, 40) [VC]', verified_at=now() where id='9684aab8-0352-4138-849e-767c2b7844a7' and verification_status not in ('verified_against_standard','corrected');
-- a_ges
