-- f_d
update public.fields set verification_status='verified_against_standard', verification_quote='3.3 Abkürzungen und Symbole | \hline $f_{\mathrm{d}}$ & - & \begin{tabular}{l} Tiefenfaktor bei der Druckluftbelüftung: \\ $1+\frac{h_{D}}{20,7}\left(1+\frac{0,5 \cdot h_{D}}{10,33}\right)$ \\ Tiefenfaktor bei der Oberflächenbelüftung: \\ $1+\frac{h_{\mathrm{BB}}}{150}$ \end{tabular} \\ — printed p.16-22', verification_note='md-verified 2026-09-07 (§3.3, printed p.16-22) [VC]', verified_at=now() where id='f08f8089-ebd5-4521-84df-d31a0649d498' and verification_status not in ('verified_against_standard','corrected');
-- SOTR
update public.fields set verification_status='verified_against_standard', verification_quote='Die Auslegung von Druckluftbelüftungssystemen geht von dem für die einzelnen Lastfälle ermittelten Sauerstoffbedarf aus. Hieraus wird die notwendige Sauerstoffzufuhr SOTR als maßgebliche Dimensionierungsgröße für die Bemessung der Belüftung ermittelt. | \text { SOTR }=\frac{f_{\mathrm{d}} \cdot C_{\mathrm{S}, 20}}{\alpha \cdot\left(f_{\mathrm{d}} \cdot C_{\mathrm{S}, \mathrm{~T}}-C_{\mathrm{x}}\right) \cdot \theta^{\left(T_{\mathrm{W}}-20\right)}} \cdot O V_{\mathrm{h}} \quad\left(\mathrm{~kg} / \mathrm{h} \mathrm{O}_{2}\right) \tag{20} — printed p.36', verification_note='md-verified 2026-09-07 (§4.3.2 Gl. (20), printed p.36) [VC]', verified_at=now() where id='f95501a6-e6ea-4043-a196-bf54e9b90ec3' and verification_status not in ('verified_against_standard','corrected');
-- alphaSOTR
update public.fields set verification_status='verified_against_standard', verification_quote='$\alpha$ SOTR (Standard Oxygen Transfer Rate) in $\mathrm{kg} / \mathrm{h}$ ist die Masse ( kg ) an Sauerstoff, die von einer Belüftungseinrichtung beim Sauerstoffgehalt von $C=0 \mathrm{mg} / \mathrm{l}$, bei einer Wassertemperatur von $T_{\mathrm{w}}=20^{\circ} \mathrm{C}$ und atmosphärischem Normaldruck ( $p_{\mathrm{N}}=1.013 \mathrm{hPa}$ ) in einer Stunde in einem mit belebtem Schlamm gefüllten Becken bestimmter Größe gelöst wird. Es gilt in Abhängigkeit der Salzfaktoren für den Betriebszustand $\beta_{\alpha}$ für die Sauerstoffsättigung und $f_{\mathrm{s}, \alpha}$ für den Belüftungskoeffizienten: | \alpha \text { SOTR }=\frac{V \cdot \alpha \cdot f_{\mathrm{S}, \alpha} \cdot k_{\mathrm{L}} a_{20} \cdot \beta_{\alpha} \cdot C_{\mathrm{S}, 20}}{1.000} \quad(\mathrm{~kg} / \mathrm{h}) \tag{2} — printed p.13', verification_note='md-verified 2026-09-07 (§3.2.3 Gl. (2), printed p.13) [VC]', verified_at=now() where id='7f8899e3-e73c-4106-b442-55487a360406' and verification_status not in ('verified_against_standard','corrected');
-- P
update public.fields set verification_status='verified_against_standard', verification_quote='3.3 Abkürzungen und Symbole | \hline $P$ & kW & Leistung \\ | Die Leistungsaufnahme $P(\mathrm{~kW})$ der Belüftungseinrichtung ist gegebenenfalls einschließlich zugehöriger Mischeinrichtungen zu bestimmen, es gilt: — printed p.16-22, 13', verification_note='md-verified 2026-09-07 (§3.3, §3.2.4, printed p.16-22, 13) [VC]', verified_at=now() where id='cda5bc50-f054-4f0b-af59-9b4dbc271b2c' and verification_status not in ('verified_against_standard','corrected');
-- SAE
update public.fields set verification_status='verified_against_standard', verification_quote='Die Leistungsaufnahme $P(\mathrm{~kW})$ der Belüftungseinrichtung ist gegebenenfalls einschließlich zugehöriger Mischeinrichtungen zu bestimmen, es gilt: | \text { SAE }=\frac{\text { SOTR }}{P} \quad(\mathrm{~kg} / \mathrm{kWh}) \tag{3} — printed p.13', verification_note='md-verified 2026-09-07 (§3.2.4 Gl. (3), printed p.13) [VC]', verified_at=now() where id='03842994-7361-40af-9361-647611e9cd47' and verification_status not in ('verified_against_standard','corrected');
-- alphaSAE
update public.fields set verification_status='verified_against_standard', verification_quote='$\alpha$ SAE in kg/kWh ist die Masse an Sauerstoff (kg), die pro Kilowattstunde (kWh) einem mit belebtem Schlamm gefüllten Becken unter Standardbedingungen zugeführt wird. Die Leistungsaufnahme $P$ (kW) der Belüftungseinrichtung ist gegebenenfalls einschließlich zugehöriger Mischeinrichtungen zu bestimmen, es gilt: | \alpha S A E=\frac{\alpha S O T R}{P} \quad(\mathrm{~kg} / \mathrm{kWh}) \tag{4} — printed p.13', verification_note='md-verified 2026-09-07 (§3.2.5 Gl. (4), printed p.13) [VC]', verified_at=now() where id='8c1eee64-efc1-4c56-b39c-50cb3aac1982' and verification_status not in ('verified_against_standard','corrected');
-- SSOTE
update public.fields set verification_status='verified_against_standard', verification_quote='Die spezifische Standard-Sauerstoffausnutzung SSOTE (Specific Standard Oxygen Transfer Efficiency) in \%/m ist ein Bezugswert, der zum Vergleich von Druckluft-Belüftungseinrichtungen benutzt wird. Es gilt mit $Q_{\mathrm{L}, \mathrm{N}}\left(\mathrm{m}^{3} / \mathrm{h}\right)$, angesaugter trockener Luft bei $T_{\mathrm{N}}=0^{\circ} \mathrm{C}$ und $p_{\mathrm{N}}=1.013 \mathrm{hPa}$ und des Sauerstoffgehalts der Luft von $300 \mathrm{~g} / \mathrm{m}^{3}\left(0,2095 \mathrm{~m}^{3} \mathrm{O}_{2} / \mathrm{m}^{3} \mathrm{Luft} \cdot 1.429 \mathrm{~g} \mathrm{O}_{2} / \mathrm{m}^{3}\right.$ Luft $)$ für die Sauerstoffausnutzung: | \text { SSOTE }=\frac{100 \cdot \text { SOTR }}{h_{\mathrm{D}} \cdot\left(Q_{\mathrm{L}, \mathrm{~N}} \cdot 0,3\right)} \quad(\% / \mathrm{m}) \tag{5} — printed p.13', verification_note='md-verified 2026-09-07 (§3.2.6 Gl. (5), printed p.13) [VC]', verified_at=now() where id='c60b1cf0-f007-47ed-b69d-cb0be183ed5f' and verification_status not in ('verified_against_standard','corrected');
-- SSOTR
update public.fields set verification_status='verified_against_standard', verification_quote='Die spezifische Standard-Sauerstoffzufuhr SSOTR (Specific Standard Oxygen Transfer Rate) in $\mathrm{g} /\left(\mathrm{m}_{\mathrm{N}}^{3} \cdot \mathrm{~m}\right)$ ist ein in Deutschland gebräuchlicher Bezugswert, für den die obigen Vorgaben gelten: | \text { SSOTR }=\frac{\text { SOTR }}{h_{\mathrm{D}} \cdot Q_{\mathrm{L}, \mathrm{~N}}} \cdot 1.000 \quad\left(\mathrm{~g} /\left(\mathrm{m}_{\mathrm{N}}^{3} \cdot \mathrm{~m}\right)\right) \tag{6} — printed p.13', verification_note='md-verified 2026-09-07 (§3.2.6 Gl. (6), printed p.13) [VC]', verified_at=now() where id='e32c8329-d49a-499c-941a-68420efe3c11' and verification_status not in ('verified_against_standard','corrected');
-- Q_L_N
update public.fields set verification_status='verified_against_standard', verification_quote='Der Luftbedarf errechnet sich schließlich unter Verwendung der spezifischen StandardSauerstoffausnutzung zu: | Q_{\mathrm{L}, \mathrm{~N}}=\frac{1.000 \cdot \text { SOTR }}{3 \cdot \text { SSOTE } \cdot h_{\mathrm{D}}} \quad\left(\mathrm{~m}_{\mathrm{N}}^{3} / \mathrm{h}\right) \tag{23} — printed p.38', verification_note='md-verified 2026-09-07 (§4.3.2 Gl. (23), printed p.38) [VC]', verified_at=now() where id='b0d7a578-bf5e-453c-8638-73a200cd13e5' and verification_status not in ('verified_against_standard','corrected');
