-- BD
update public.fields set verification_status='verified_against_standard', verification_quote='Die Belegungsdichte ( $B D$ ) ergibt sich als Verhältnis der abgasenden Fläche der Belüfter ( $n_{\text {Bel }} \cdot a_{\text {Bel }}$ ) durch die Beckengrundfläche ( $A_{\mathrm{BB}}$ ). | B D=\frac{n_{\mathrm{Bel}} \cdot a_{\mathrm{Bel}}}{A_{\mathrm{BB}}} | Die Belegungsdichte wird grundsätzlich nur für Becken mit flächendeckender Belüftung angegeben und kann in Abhängigkeit der verfahrenstechnischen Funktion der Becken (Selektor, reiner Kohlenstoffabbau, Nitrifikation, simultan aerobe Schlammstabilisierung) Werte zwischen $5 \%$ und $25 \%$ annehmen. — printed p.14', verification_note='md-verified 2026-09-07 (§3.2.9, printed p.14) [VC]', verified_at=now() where id='540221ed-fb09-4f56-9f7c-a35968cd64e8' and verification_status not in ('verified_against_standard','corrected');
