-- SOTR_alt
update public.fields set verification_status='verified_against_standard', verification_quote='Ab einer Höhe von 600 m . ü. NN und bei Salzgehalten $S_{\text {TDS }, \alpha}<2 \mathrm{~g} / \mathrm{l}$ wird empfohlen, zusätzlich auch noch den Einfluss der Höhenlage auf die Sauerstoffsättigungskonzentration zu berücksichtigen: | \text { SOTR }=\frac{f_{\mathrm{d}} \cdot C_{\mathrm{S}, 20}}{\alpha \cdot\left(f_{\mathrm{d}} \cdot C_{\mathrm{S}, \mathrm{~T}} \cdot \frac{p_{\mathrm{atm}}}{1.013}-C_{\mathrm{x}}\right) \cdot \theta^{\left(T_{\mathrm{w}}-20\right)}} \cdot O V_{\mathrm{h}} \quad\left(\mathrm{~kg} / \mathrm{h} \mathrm{O}_{2}\right) \tag{21} — printed p.36', verification_note='md-verified 2026-09-07 (§4.3.2 Gl. (21), printed p.36) [VC]', verified_at=now() where id='7a709aa2-5dc2-4f50-8839-6e792d8385b4' and verification_status not in ('verified_against_standard','corrected');
-- SOTR_salz
update public.fields set verification_status='verified_against_standard', verification_quote='Bei Salzgehalten $S_{\text {TDS }, \alpha}>2 \mathrm{~g}$ TDS/l sollten die Einflüsse des Salzes im Abwasser auf den Sauerstoffsättigungswert ( $\beta_{\mathrm{St}}$ und $\beta_{\alpha}$ ) und auf den Belüftungskoeffizienten ( $f_{\mathrm{S}, \mathrm{St}}$ und $f_{\mathrm{S}, \alpha}$ ) berücksichtigt werden: | \text { SOTR }=\frac{f_{\mathrm{d}} \cdot \beta_{\mathrm{St}} \cdot C_{\mathrm{S}, 20} \cdot f_{\mathrm{S}, \mathrm{St}}}{\alpha \cdot f_{\mathrm{S}, \alpha} \cdot\left(f_{\mathrm{d}} \cdot \beta_{\alpha} \cdot C_{\mathrm{S}, \mathrm{~T}} \cdot \frac{p_{\mathrm{atm}}}{1.013}-C_{\mathrm{x}}\right) \cdot \theta^{\left(T_{\mathrm{W}}-20\right)}} \cdot O V_{\mathrm{h}} \quad\left(\mathrm{~kg} / \mathrm{h} \mathrm{O}_{2}\right) \tag{22} — printed p.36', verification_note='md-verified 2026-09-07 (§4.3.2 Gl. (22), printed p.36) [VC]', verified_at=now() where id='f2be2cc9-fc19-4628-9ed8-f08ffa130bb4' and verification_status not in ('verified_against_standard','corrected');
