-- p_atm
update public.fields set verification_status='verified_against_standard', verification_quote='Für eine genaue Ermittlung der erforderlichen Luftmenge ist zunächst der Luftdruck ( $p_{\text {atm }}$ ) in Abhängigkeit von der geodätischen Höhenlage der Anlage zu ermitteln: | p_{\text {atm }}=1.013,25 \cdot\left(\frac{288-0,0065 \cdot h_{\text {geo }}}{288}\right)^{5,255} \quad \text { (hPa) } \tag{26} — printed p.38', verification_note='md-verified 2026-09-07 (§4.3.2 Gl. (26), printed p.38) [VC]', verified_at=now() where id='d1ac8ada-2e40-49d1-bf47-113467c6a0fd' and verification_status not in ('verified_against_standard','corrected');
