update public.fields set verification_status='verified_against_standard', verification_quote='Abzüglich der Verluste auf der Saugseite ( z . B. Luftfilter, Saugleitung: $\Delta p_{1}$ ) errechnet sich der Ansaugdruck ( $p_{1, \text { abs }}$ ) zu: | p_{1, \text { abs }}=p_{\text {atm }}-\Delta p_{1} \quad \text { (hPa) } \tag{27} — printed p.38', verification_note='md-verified 2026-09-07 (§4.3.2 Gl. (27), printed p.38) [VC]', verified_at=now() where id='79c816de-996a-4684-98c3-6f120b51488e' and verification_status not in ('verified_against_standard','corrected');
