update public.fields set verification_status='verified_against_standard', verification_quote='Die Dichte im Ansaugzustand ( $\rho_{1}$ ) lässt sich wie folgt ermitteln: | \rho_{1}=\rho_{\mathrm{N}} \cdot \frac{T_{\mathrm{N}}}{T_{\mathrm{N}}+T_{\mathrm{L}, 1}} \cdot \frac{p_{1, \mathrm{abs}}-\varphi \cdot p_{\mathrm{S}}}{p_{\mathrm{N}}}+\varphi \cdot \rho_{\mathrm{S}} \quad\left(\mathrm{~kg} / \mathrm{m}^{3}\right) \tag{28} — printed p.38', verification_note='md-verified 2026-09-07 (§4.3.2 Gl. (28), printed p.38) [VC]', verified_at=now() where id='7afd1c19-42ae-4fff-80af-2f552a74deda' and verification_status not in ('verified_against_standard','corrected');
-- Q_1
update public.fields set verification_status='verified_against_standard', verification_quote='Damit ergibt sich der Ansaugvolumenstrom ( $Q_{1}$ ) schließlich zu: | Q_{1}=\frac{T_{\mathrm{N}}+T_{\mathrm{L}, 1}}{T_{\mathrm{N}}} \cdot \frac{p_{\mathrm{N}}}{p_{1, \mathrm{abs}}-\varphi \cdot p_{\mathrm{S}}} \cdot Q_{\mathrm{L}, \mathrm{~N}} \quad\left(\mathrm{~m}^{3} / \mathrm{min}\right) \tag{29} — printed p.38', verification_note='md-verified 2026-09-07 (§4.3.2 Gl. (29), printed p.38) [VC]', verified_at=now() where id='5601c46b-e14a-4f42-a9a5-5b5c2ce03032' and verification_status not in ('verified_against_standard','corrected');
