update public.fields set verification_status='verified_against_standard', verification_quote='3.3 Abkürzungen und Symbole | \hline $\Delta p$ & hPa & erforderliche Druckerhöhung \\ | Weiterhin ist für die Gebläseauslegung der Differenzdruck als Summe aller Verluste im Belüftungssystem zu ermitteln. Neben der Einblastiefe sind hier vor allem die Druckdifferenz der Belüfterelemente und der Druckverlust im Rohrleitungssystem einschließlich aller Armaturen und Einbauten zu berücksichtigen. — printed p.16-22, 39', verification_note='md-verified 2026-09-07 (§3.3, §4.3.2, printed p.16-22, 39) [VC]', verified_at=now() where id='8378cb30-c3a8-4675-84ec-b04a6b88da66' and verification_status not in ('verified_against_standard','corrected');
