update public.fields set verification_status='verified_against_standard', verification_quote='\caption{Tabelle 4: Leistungs- und Regelbereich von Oberflächenbelüftern} | \hline Belüftertyp & Mögliche Sauerstoffzufuhr $S O T R_{\text {max }}$ in $\mathrm{kg} / \mathrm{h}$ & Art der Regelung/Steuerung & Wirtschaftlicher Regelbereich in \% von SOTR ${ }_{\text {max }}$ \\ | \hline \multirow[t]{3}{*}{Kreisel} & \multirow[t]{3}{*}{5-450} & intermittierend: & 0-100 \\ | \hline \multirow[t]{3}{*}{Walzen} & \multirow[t]{3}{*}{5-90 bzw. $5-9 \mathrm{~kg} /(\mathrm{m} \cdot \mathrm{h})$} & intermittierend: & 0-100 \\ — printed p.41', verification_note='md-verified 2026-09-07 (§4.3.3 Tabelle 4, printed p.41) [VC]', verified_at=now() where id='581ec8ea-b2f9-44e6-8a59-93edb2972037' and verification_status not in ('verified_against_standard','corrected');
