-- ---------------------------------------------------------------- M2291-07
-- v_bodennah
update public.fields set verification_status='verified_against_standard', verification_quote='Bei einem gut absetzbaren Schlamm ( $/$ SV $<80 \mathrm{ml} / \mathrm{g}$ ) und geringen Feststoffkonzentrationen im Belebungsbecken ( $T S_{\mathrm{BB}}<2 \mathrm{~g} / \mathrm{l}$ ) mit entsprechend höheren Sinkgeschwindigkeiten ist davon auszugehen, dass eine bodennahe Geschwindigkeit von mindestens $0,25 \mathrm{~m} / \mathrm{s}$ zur Vermeidung von Ablagerungen ausreichend ist | Bei schwerer absetzbarem Schlamm ( $/$ SV $>130 \mathrm{ml} / \mathrm{g}$ ) und höheren Feststoffgehalten ( $T S_{B B}>4 \mathrm{~g} / \mathrm{l}$ ) und damit geringeren Sinkgeschwindigkeiten des belebten Schlamms kann von einer bodennahen Geschwindigkeit von mehr als $0,1 \mathrm{~m} / \mathrm{s}$ ausgegangen werden, um Ablagerungen zu vermeiden. — printed p.46', verification_note='md-verified 2026-09-07 (§5.4, printed p.46) [VC]', verified_at=now() where id='74ef902f-e691-4b47-b9cf-8616b0c1103c' and verification_status not in ('verified_against_standard','corrected');
-- D_Ruehr
update public.fields set verification_status='verified_against_standard', verification_quote='3.3 Abkürzungen und Symbole | \hline $D_{\text {Rühr }}$ & m & Durchmesser des Rührwerks \\ | Tauchrührwerke beeinflussen sich aber auch gegenseitig im Saugbereich, sodass zwischen den Rührwerken ein Abstand von $>D_{\text {Rühr }}$ eingehalten werden oder durch eine Trennwand dieser Einfluss vermieden werden muss. — printed p.16-22, 45', verification_note='md-verified 2026-09-07 (§3.3, §5.3.4, printed p.16-22, 45) [VC]', verified_at=now() where id='6d420b3c-1492-4e97-906c-464b33113bbd' and verification_status not in ('verified_against_standard','corrected');
-- schub_Ruehr
update public.fields set verification_status='verified_against_standard', verification_quote='Zu den Leistungsparametern eines Rührwerks gehören neben Angaben zum Fabrikat, Typ, Rührorgan, Flügelzahl, Durchmesser und Drehzahl im Wesentlichen die Leistungsaufnahme ( kW ) und der Rührwerksschub (N). | Zur Feststellung der Effizienz von Rührwerken sind ISO 21630 und das VDMA-Einheitsblatt 24656 zu beachten. Darin wird der Schub (Kraft, die vom Rührwerk auf das Wasser wirkt) als wichtiger Parameter eingeführt. Um Rührwerke verschiedener Bauweisen und verschiedener Hersteller besser vergleichen zu können, wird die spezifische Schubleistung (N/kW) abgeleitet. Je größer die spezifische Schubleistung ist, desto effektiver ist das Rühraggregat. — printed p.45, 64', verification_note='md-verified 2026-09-07 (§5.3.3.2, §9.1.3.3, printed p.45, 64) [VC]', verified_at=now() where id='345df8ab-e042-410e-b445-fb1ba19b2b15' and verification_status not in ('verified_against_standard','corrected');
-- abstand_ruehr_beluefter
update public.fields set verification_status='verified_against_standard', verification_quote='Von den Rührwerksherstellern werden Mindestwerte für Wandabstand, Sohlenabstand, Abstand zu Belüftern, der Wasseroberfläche und der Rührwerke untereinander gefordert (Higbie 1935). Die Angaben der verschiedenen Hersteller sind nicht einheitlich. Typische Werte sind: | - Abstand zwischen Rührwerk und Belüfterfeld | sowie zu Umlenkungen (in beiden Richtungen): $4 m-7 m$ — printed p.49', verification_note='md-verified 2026-09-07 (§6.2.2, printed p.49) [VC]', verified_at=now() where id='b531cc29-6e9d-48cc-a8b4-c1b48a27d31b' and verification_status not in ('verified_against_standard','corrected');
-- ruehraufgabe
update public.fields set verification_status='verified_against_standard', verification_quote='Rührwerke in Abwasserreinigungsanlagen haben im Wesentlichen folgende Aufgaben: | I Homogenisieren (Ausgleich von Konzentrations- und Temperaturgefälle), | I Suspendieren (Vermeidung und Mobilisierung von Ablagerungen) im System fest/flüssig bzw. fest/flüssig/gasförmig, | I Vermeiden von Kurzschlussströmungen, | I Einbringen einer gerichteten Strömung. — printed p.43', verification_note='md-verified 2026-09-07 (§5.1, printed p.43) [VC]', verified_at=now() where id='64208e5d-9a9a-413a-bd55-b95b8e2e092e' and verification_status not in ('verified_against_standard','corrected');
-- n_Ruehr
update public.fields set verification_status='verified_against_standard', verification_quote='Die Anzahl der Rühraggregate ergibt sich aus den Anforderungen und den Leistungsparametern des gewählten Rühraggregats. — printed p.45', verification_note='md-verified 2026-09-07 (§5.3.3.1, printed p.45) [VC]', verified_at=now() where id='90fd3507-032d-4872-a70d-41fac689eb57' and verification_status not in ('verified_against_standard','corrected');
-- P_BB_Ruehr
update public.fields set verification_status='verified_against_standard', verification_quote='Bezogen auf ein Becken ergibt sich aus der Leistungsaufnahme der spezifische Leistungseintrag $\left(\mathrm{W} / \mathrm{m}^{3}\right)$, der als weiterer Leistungsparameter für ein Becken bezeichnet werden kann. | Typische Werte für den spezifischen Leistungseintrag liegen im Bestand heute zwischen $2 \mathrm{~W} / \mathrm{m}^{3}$ bis $5 \mathrm{~W} / \mathrm{m}^{3}$, wobei im Rahmen von energetischen Optimierungen oder bei Neuplanungen in Abhängigkeit der jeweiligen Randbedingungen auch mit deutlich geringeren Leistungseinträgen von bis zu unter $1 \mathrm{~W} / \mathrm{m}^{3}$ unter Umständen eine ausreichende Durchmischung erreicht werden kann. Mit den heute verfügbaren Rührwerken mit integrierter Drehzahlverstellung kann eine optimale Anpassung an die jeweilige Aufgabenstellung erfolgen. — printed p.45', verification_note='md-verified 2026-09-07 (§5.3.3.2, printed p.45) [VC]', verified_at=now() where id='013962c5-d113-4193-af7d-898f9d6bb6d1' and verification_status not in ('verified_against_standard','corrected');
-- q_L_misch
update public.fields set verification_status='verified_against_standard', verification_quote='Die Ermittlung der Mischenergie dient der Überprüfung der Durchmischung in Zeiten geringer Belüftung (z. B. im Nachtbetrieb) bzw. bei Stoß- bzw. Impulsbelüftung. | Unter der Annahme, dass für die Mischung das Luftvolumen bezogen auf die Zustandsgrößen in halber Einblastiefe maßgeblich ist, gilt: | q_{\mathrm{L}}=\frac{P_{\mathrm{BB}}}{2,72} \cdot \frac{\left(1.013+98,1 \cdot \frac{h_{\mathrm{D}}}{2}\right)}{1.013 \cdot h_{\mathrm{D}}} \cdot \frac{273}{\left(273+T_{\mathrm{W}}\right)} \tag{D.2} — printed p.96', verification_note='md-verified 2026-09-07 (Anhang D Gl. (D.2), printed p.96) [VC]', verified_at=now() where id='8939eafa-7587-400f-87b4-d94fe9d51d97' and verification_status not in ('verified_against_standard','corrected');
-- TS_BB
update public.fields set verification_status='verified_against_standard', verification_quote='3.3 Abkürzungen und Symbole | \hline $T S_{\text {BB }}$ & $\mathrm{kg} / \mathrm{m}^{3}$ & Feststoffgehalt des belebten Schlamms im Belebungsbecken \\ | Mit Medium wird der zu rührende Beckeninhalt bezeichnet. Im Rahmen der kommunalen Abwasserreinigung mit TS-Werten in den Denitrifikations- und Nitrifikationsbecken von $2 \mathrm{~g} / \mathrm{l} \mathrm{bis} 5 \mathrm{~g} / \mathrm{l}$ ist von keinen wesentlichen Viskositätsveränderungen gegenüber Reinwasser auszugehen, die zu einer Leistungsminderung der Rühraggregate führen können. — printed p.16-22, 44', verification_note='md-verified 2026-09-07 (§3.3, §5.3.2.2, printed p.16-22, 44) [VC]', verified_at=now() where id='74fdd77f-37af-4070-8f7b-9caf9323f003' and verification_status not in ('verified_against_standard','corrected');
-- ISV
update public.fields set verification_status='verified_against_standard', verification_quote='3.3 Abkürzungen und Symbole | \hline ISV & $\mathrm{ml} / \mathrm{g}$ & Schlammvolumenindex \\ | einschließlich der Schlammeigenschaften ( $T S_{\text {BB }}$, ISV) Angaben zur Rühraufgabe — printed p.16-22, 46', verification_note='md-verified 2026-09-07 (§3.3, §5.4, printed p.16-22, 46) [VC]', verified_at=now() where id='31dfefba-049b-466d-82fd-d77a1841458c' and verification_status not in ('verified_against_standard','corrected');

-- ---------------------------------------------------------------- M2291-08
-- cfd_simulation
update public.fields set verification_status='verified_against_standard', verification_quote='Im Gegensatz dazu bieten mehrdimensionale mathematische Modelle - sogenannte CFD-Modelle (CFD Computational Fluid Dynamics) - die Möglichkeit, ein einzelnes Becken räumlich abzubilden und einen umfassenden Einblick in die ablaufenden Prozesse zu erhalten (Hunze 2005). | Die Durchführung 3 -dimensionaler Strömungssimulationen wird zur Unterstützung von Neuplanungen, Sanierungen und Optimierungen eingesetzt. Fragestellungen im Hinblick auf die Positionierung der Aggregate wie Belüfter und Rührwerke und ihr Einfluss auf die sich einstellenden Systemverhältnisse können untersucht und eine verfahrenstechnisch optimale wie auch energieeffiziente Betriebsweise des Beckens ermittelt werden. — printed p.56', verification_note='md-verified 2026-09-07 (§7, printed p.56) [VC]', verified_at=now() where id='c7955605-f49b-49df-ba30-6fc7f826cbfe' and verification_status not in ('verified_against_standard','corrected');
-- abstand_beluefter_achse
update public.fields set verification_status='verified_against_standard', verification_quote='Für Rohrbelüfter zeigen praktische Erfahrungen, dass sich bei zu großen Abständen zwischen den Rohrenden von Belüfterfeldern, beispielsweise mehr als 800 mm bei einer Wassertiefe von ca. $5,5 \mathrm{~m}$, Strömungswalzen einstellen, die meist negativ auf den Sauerstoffeintrag wirken. Weiterhin sollte der Abstand von Achse zu Achse zweier Rohrbelüfter einen Wert von ca. 500 mm nicht überschreiten. — printed p.48', verification_note='md-verified 2026-09-07 (§6.2.1, printed p.48) [VC]', verified_at=now() where id='30a8620f-6c04-421f-a996-1b201fff3a35' and verification_status not in ('verified_against_standard','corrected');
-- abstand_walzenbeluefter
update public.fields set verification_status='verified_against_standard', verification_quote='Die Anordnung der Walzenbelüfter beeinflusst in erheblichem Maße die Effektivität des Sauerstoffeintrags wie auch die Ausbildung des Strömungsfelds. Um negative Beeinflussungen auf den Sauerstoffeintrag so gering wie möglich zu halten, ist der Abstand zwischen den Walzenbelüftern so groß wie möglich zu wählen, wobei ein Mindestabstand von 20 m nur in Sonderfällen unterschritten werden sollte (siehe Bild 6). — printed p.52', verification_note='md-verified 2026-09-07 (§6.2.3.2, printed p.52) [VC]', verified_at=now() where id='4c0aba7a-4fda-4c91-99d2-afb61269b16e' and verification_status not in ('verified_against_standard','corrected');
-- leitschild_vorhanden
update public.fields set verification_status='verified_against_standard', verification_quote='Walzenbelüfter sollten grundsätzlich nur in Kombination mit Leitschilden betrieben werden, da diese eine Steigerung des Sauerstoffeintrags um bis zu $20 \%$ bewirken. Die Anordnung von Leitschilden und die wesentlichen Maße verdeutlicht Bild 9. — printed p.53', verification_note='md-verified 2026-09-07 (§6.2.3.2, printed p.53) [VC]', verified_at=now() where id='96e52b13-83e0-401e-a57e-31160d34fe8e' and verification_status not in ('verified_against_standard','corrected');
-- breite_tiefe_verhaeltnis
update public.fields set verification_status='verified_against_standard', verification_quote='Für einen wirtschaftlichen Betrieb hinsichtlich des Sauerstoffeintrags wird ein Verhältnis von Beckenbreite zu Beckentiefe von $>4$ für Rechteckbecken empfohlen. Die Wassertiefe beträgt bei Rechteckbecken bis zu 4,50 m und bei Umlaufbecken bis zu 5,0 m. — printed p.54', verification_note='md-verified 2026-09-07 (§6.2.3.3, printed p.54) [VC]', verified_at=now() where id='b32b3aa7-9ce6-4844-9605-8e4128801544' and verification_status not in ('verified_against_standard','corrected');

-- ---------------------------------------------------------------- M2291-09
-- nutzungsdauer
update public.fields set verification_status='verified_against_standard', verification_quote='Zur Wahl einer geeigneten Nutzungsdauer gibt die Tabelle 6 entsprechende Hinweise. | \caption{Tabelle 6: Empfohlene Nutzungsdauer ( $n$ ) für Wirtschaftlichkeitsvergleiche in Jahren (a)} | \hline Element & Nutzungsdauer in Jahren (a) \\ \hline Bauwerke & 30 \\ \hline Belüfterelemente Elastomere & 5-10 \\ \hline Belüfterelemente starr-porös & 15-20 \\ \hline Rührwerke & 15 \\ \hline Drucklufterzeuger & 10-20 \\ \hline Rohrleitungen & 30 \\ \hline Oberflächenbelüfter & 10-20 \\ \hline EMSR-Technik & 10 \\ — printed p.58-59', verification_note='md-verified 2026-09-07 (§8.2 Tabelle 6, printed p.58-59) [VC]', verified_at=now() where id='63d453f9-7305-4404-9bf8-359706b72444' and verification_status not in ('verified_against_standard','corrected');
-- investitionskosten
update public.fields set verification_status='verified_against_standard', verification_quote='Zu den Investitionskosten bei einem Wirtschaftlichkeitsvergleich von Belüftungssystemen zählen insbesondere: | I Baukosten für Gebläsestation bei Druckbelüftungssystemen, I Drucklufterzeugung, I Rohrleitungen und Armaturen, I Oberflächenbelüfter, I Baukosten für Befestigungsbrücken bei Oberflächenbelüftung, - Belüfterelemente, I Durchmischungsaggregate einschließlich der Baukosten für Brücken und Befestigung, I EMSR-Technik. — printed p.58', verification_note='md-verified 2026-09-07 (§8.2, printed p.58) [VC]', verified_at=now() where id='cc2b85fd-c72b-4e42-bfc7-f65bcc545f8c' and verification_status not in ('verified_against_standard','corrected');
-- wartungssatz_mt
update public.fields set verification_status='verified_against_standard', verification_quote='Zu den laufenden Kosten bei einem Wirtschaftlichkeitsvergleich von Belüftungssystemen zählen: | I Wartungs- und Instandhaltungskosten: | $1,5 \%$ für die Maschinentechnik, | $2,5 \%$ für die EMSR-Technik. — printed p.59', verification_note='md-verified 2026-09-07 (§8.3, printed p.59) [VC]', verified_at=now() where id='30fbfba6-5fea-4982-825a-0b26cbc24582' and verification_status not in ('verified_against_standard','corrected');
-- wartungssatz_emsr
update public.fields set verification_status='verified_against_standard', verification_quote='Zu den laufenden Kosten bei einem Wirtschaftlichkeitsvergleich von Belüftungssystemen zählen: | I Wartungs- und Instandhaltungskosten: | $1,5 \%$ für die Maschinentechnik, | $2,5 \%$ für die EMSR-Technik. — printed p.59', verification_note='md-verified 2026-09-07 (§8.3, printed p.59) [VC]', verified_at=now() where id='ab52fc91-3730-4136-9d68-7e5b795fa9e8' and verification_status not in ('verified_against_standard','corrected');
-- realzinssatz
update public.fields set verification_status='verified_against_standard', verification_quote='Bei der Annahme eines Realzinssatzes wird grundsätzlich empfohlen, mit einem Wert von $3 \% \mathrm{zu}$ rechnen, in dem sowohl der Nominalzinssatz wie auch die Inflation eingerechnet sind (DWA 2012). Grundsätzlich sollte aber, insbesondere bei stark unterschiedlichen Anteilen von Investitionskosten und laufenden Kosten, eine Empfindlichkeitsprüfung im Sinne einer Szenarienuntersuchung durchgeführt werden und der Realzinssatz in einem Bereich zwischen z. B. $2 \%$ und $6 \%$ variiert werden. — printed p.60', verification_note='md-verified 2026-09-07 (§8.4, printed p.60) [VC]', verified_at=now() where id='bfb2a4fd-ad3b-47fa-a3f2-85f953a3b0de' and verification_status not in ('verified_against_standard','corrected');
-- jahreskosten
update public.fields set verification_status='verified_against_standard', verification_quote='Auf Basis der ermittelten Investitions- und Betriebskosten werden dann unter Verwendung der finanzmathematischen Umrechnungen der Kostenvergleichsrechnung (DWA 2012) die Jahreskosten bzw. die Projektkostenbarwerte ermittelt. | Eine beispielhafte Kostenvergleichsrechnung für die Untersuchung der Wirtschaftlichkeit zweier unterschiedlicher Belüftungssysteme findet sich in Anhang A.2. — printed p.60', verification_note='md-verified 2026-09-07 (§8.4, printed p.60) [VC]', verified_at=now() where id='344cafa3-8d91-4972-99c3-655c9b6a49b4' and verification_status not in ('verified_against_standard','corrected');
-- projektkostenbarwert
update public.fields set verification_status='verified_against_standard', verification_quote='Auf Basis der ermittelten Investitions- und Betriebskosten werden dann unter Verwendung der finanzmathematischen Umrechnungen der Kostenvergleichsrechnung (DWA 2012) die Jahreskosten bzw. die Projektkostenbarwerte ermittelt. | Eine beispielhafte Kostenvergleichsrechnung für die Untersuchung der Wirtschaftlichkeit zweier unterschiedlicher Belüftungssysteme findet sich in Anhang A.2. — printed p.60', verification_note='md-verified 2026-09-07 (§8.4, printed p.60) [VC]', verified_at=now() where id='7f98a030-a30d-43ab-9046-39f68461735e' and verification_status not in ('verified_against_standard','corrected');
-- energiekosten
update public.fields set verification_status='verified_against_standard', verification_quote='I Energiekosten: | für den Betrieb der Verdichter bei Druckbelüftungssystemen bzw. von Oberflächenbelüftern und für den Betrieb von Durchmischungsaggregaten; | Die Energiekosten für den Wirtschaftlichkeitsvergleich werden aus dem Lastfall 1 (siehe 4.3.1) abgeleitet und müssen sich damit immer auf den Sauerstoff- bzw. Energiebedarf im Jahresmittel beziehen. — printed p.59', verification_note='md-verified 2026-09-07 (§8.3, printed p.59) [VC]', verified_at=now() where id='303f8ee8-4a97-4d0f-9ced-415f70c3eaf9' and verification_status not in ('verified_against_standard','corrected');

-- ---------------------------------------------------------------- M2291-10
-- garantie_druckverlust
update public.fields set verification_status='verified_against_standard', verification_quote='Für Druckbelüftungen sollte zusätzlich der Druckverlust an den Belüfterelementen im Neuzustand garantiert werden. Darüber hinaus ist es sinnvoll, vom Hersteller eine Angabe zum Druckverlustanstieg in Abhängigkeit der Betriebszeit, beispielsweise nach 1, 3, 5 oder 8 Jahren Betriebszeit, zu fordern. — printed p.63', verification_note='md-verified 2026-09-07 (§9.1.3.2, printed p.63) [VC]', verified_at=now() where id='001f1acb-4f04-4e19-bc1c-3654e4cc33c9' and verification_status not in ('verified_against_standard','corrected');
-- abnahme_messmedium
update public.fields set verification_status='verified_against_standard', verification_quote='Garantiemessungen für Belüftungssysteme sollten vorzugsweise im Reinwasser erfolgen, da nur so optimale Voraussetzungen für reproduzierbare und vergleichbare Messungen vorliegen. | Garantiemessungen werden meist in Reinwasser durchgeführt, da sich die Hersteller bzw. Ausrüster nicht in der Lage sehen, die anlagenspezifischen Einflüsse hinreichend genau zu quantifizieren. — printed p.68, 63', verification_note='md-verified 2026-09-07 (§9.3, §9.1.3.2, printed p.68, 63) [VC]', verified_at=now() where id='774c254a-2e87-4f41-bd9c-1e41008d5da8' and verification_status not in ('verified_against_standard','corrected');
-- garantie_sauerstoffertrag
update public.fields set verification_status='verified_against_standard', verification_quote='Bei neu gebauten Anlagen sollte die Garantie alle Bereiche umfassen, also Sauerstoffzufuhr, Sauerstoffertrag und auch die Durchmischung. | Der Sauerstoffertrag sollte als Maß für die Wirtschaftlichkeit vorrangig bei der mittleren Betriebseinstellung ermittelt werden. — printed p.62-63', verification_note='md-verified 2026-09-07 (§9.1.3.2, printed p.62-63) [VC]', verified_at=now() where id='202f8b12-afcc-43d4-94c8-8e3dea8009da' and verification_status not in ('verified_against_standard','corrected');
-- garantie_sauerstoffzufuhr
update public.fields set verification_status='verified_against_standard', verification_quote='Eine Überprüfung der Garantiewerte von Belüftern und Durchmischungsaggregaten sollte grundsätzlich erfolgen, wenn die Anlage eine Ausbaugröße von mehr als 100.000 EW aufweist oder wenn es sich bei dem ausgeführten Belüftungssystem um einen Sondervorschlag handelt. | Für gleichzeitig belüftete und durchmischte Belebungsbecken müssen für die Sauerstoffzufuhr und die Durchmischung getrennte Garantiewerte formuliert werden. — printed p.62', verification_note='md-verified 2026-09-07 (§9.1.3.1, printed p.62) [VC]', verified_at=now() where id='c1b73b6f-0ca4-4047-a465-6db59f24c99f' and verification_status not in ('verified_against_standard','corrected');
-- ausbaugroesse_EW
update public.fields set verification_status='verified_against_standard', verification_quote='Eine Überprüfung der Garantiewerte von Belüftern und Durchmischungsaggregaten sollte grundsätzlich erfolgen, wenn die Anlage eine Ausbaugröße von mehr als 100.000 EW aufweist oder wenn es sich bei dem ausgeführten Belüftungssystem um einen Sondervorschlag handelt. | Für Anlagen im Bereich von 10.000 EW bis 100.000 EW wird eine Überprüfung empfohlen. Für kleinere Anlagen (unter 10.000 EW ) kann auf den Nachweis des Sauerstoffeintrags und -ertrags in Reinwasser verzichtet werden, wenn der Ausrüster oder Hersteller entsprechende Ergebnisse baugleicher Anlagen vorlegen kann. — printed p.62', verification_note='md-verified 2026-09-07 (§9.1.3.1, printed p.62) [VC]', verified_at=now() where id='ee10f2bb-aef4-4471-b0d7-790ec69e63c0' and verification_status not in ('verified_against_standard','corrected');
-- ausschreibungsart
update public.fields set verification_status='verified_against_standard', verification_quote='Üblicherweise werden in vielen Fällen die Belüftung und die Rührwerke im Rahmen der gesamten klärtechnischen Ausrüstung in Einzelpositionen ausgeschrieben, sodass die Belüftung oder Rührwerke nur einen Teil der Liefer- und Montagekomponenten darstellt. | Als Alternative besteht die Möglichkeit, die Belüftung komplett mit den notwendigen Peripherieeinrichtungen und den gegebenenfalls notwendigen Aggregaten zur Durchmischung wie auch die Durchmischung selbst als gesamtheitliche Funktionalausschreibung zur Vergabe auszuschreiben. — printed p.60', verification_note='md-verified 2026-09-07 (§9.1.1, printed p.60) [VC]', verified_at=now() where id='8eabf13e-0ca1-4b49-8de0-05294a8d5bcf' and verification_status not in ('verified_against_standard','corrected');
-- druckueberwachung
update public.fields set verification_status='verified_against_standard', verification_quote='Ebenso sollte bei Druckluftbelüftungssystemen bereits bei der Planung eine Drucküberwachung berücksichtigt werden. Dies kann in einfacher Weise durch eine manometrische Drucküberwachung in der Luftleitung unmittelbar vor der Verteilung auf die einzelnen Belüftungsstränge am Beckenrand geschehen. Der Druck wird monatlich bei annähernd gleichem Luftvolumenstrom erfasst und im Betriebstagebuch notiert. — printed p.42', verification_note='md-verified 2026-09-07 (§4.4, printed p.42) [VC]', verified_at=now() where id='0e016fdf-7564-4e9f-9f23-1257ad58e255' and verification_status not in ('verified_against_standard','corrected');
-- energiezaehler_belueftung
update public.fields set verification_status='verified_against_standard', verification_quote='Es wird empfohlen, die Leistungsaufnahme der Belüftung zumindest als Gesamtgröße mittels eines Energiezählers zu erfassen und kontinuierlich im PLS aufzuzeichnen. Bei größeren Anlagen kann es auch sinnvoll sein, die Energie für die Belüftung von einzelnen Becken bzw. durch einzelne Aggregate (z. B. Gebläse, Walzenbelüfter) zu erfassen. — printed p.42', verification_note='md-verified 2026-09-07 (§4.4, printed p.42) [VC]', verified_at=now() where id='d8a355f9-7397-4ef3-ae8b-8a83e92b29af' and verification_status not in ('verified_against_standard','corrected');
-- doppelmessung
update public.fields set verification_status='verified_against_standard', verification_quote='Den geltenden Richtlinien entsprechend sollten Garantiemessungen bei diskontinuierlichen Messverfahren wie der Absorptions- bzw. Desorptionsmethode als Doppelmessungen ausgeführt werden - Ausnahmen sollten nur in begründeten Fällen zugelassen sein, z. B. wenn das Messprogramm sehr umfangreich ist, also beispielsweise Messungen bei mehr als zwei Betriebseinstellungen am selben System vorgesehen sind oder wenn sich bei der Vor-Ort-Auswertung zweifelsfrei herausstellt, dass Garantiewerte nicht erreicht werden und durch geänderte Einstellung des Belüftungssystems die Möglichkeit geschaffen wird, der Ursache des Problems nachzugehen. — printed p.68', verification_note='md-verified 2026-09-07 (§9.3, printed p.68) [VC]', verified_at=now() where id='21bd512e-d3a0-4d7a-a930-86db3eaef27b' and verification_status not in ('verified_against_standard','corrected');

-- ================================= EQUATIONS =================================
-- Equations that already carry verification_status='verified_against_standard' but a NULL
-- verification_quote get a QUOTE BACKFILL ONLY, guarded on "verification_quote is null"; their
-- status is not touched. Equations at 'verified_via_cross_reference' get the full update.

-- M2291-02 OV_h_aM (Gl. 15)
update public.equations set verification_quote='I Lastfall 1: Durchschnittlicher Sauerstoffbedarf im Ist-Zustand, $O V_{\mathrm{h}, \mathrm{aM}}$ | O V_{\mathrm{h}, \mathrm{aM}}=\frac{\left(O V_{\mathrm{d}, \mathrm{C}, \mathrm{aM}}-O V_{\mathrm{d}, \mathrm{D}, \mathrm{aM}}\right)+O V_{\mathrm{d}, \mathrm{~N}, \mathrm{aM}}}{24} \quad\left(\mathrm{~kg} / \mathrm{h} \mathrm{O}_{2}\right) \tag{14} — printed p.34', verification_note='md-verified 2026-09-07 (§4.3.1 Gl. (14), printed p.34) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='0b44370a-a62d-4fb9-9f76-f8d0be42502d' and verification_quote is null;
-- M2291-02 OV_h_max (Gl. 16)
update public.equations set verification_quote='I Lastfall 2: Maximaler Sauerstoffbedarf im Ist-Zustand, $O V_{\mathrm{h}, \max }$ | O V_{\mathrm{h}, \text { max }}=\frac{f_{\mathrm{C}} \cdot\left(O V_{\mathrm{d}, \mathrm{C}, \text { max }}-O V_{\mathrm{d}, \mathrm{D}, \text { max }}\right)+f_{\mathrm{N}} \cdot O V_{\mathrm{d}, \mathrm{~N}, \text { max }}}{24} \quad\left(\mathrm{~kg} / \mathrm{h} \mathrm{O}_{2}\right) \tag{15} — printed p.34', verification_note='md-verified 2026-09-07 (§4.3.1 Gl. (15), printed p.34) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='1bccdbcd-032a-4293-9a58-26d31c94c774' and verification_quote is null;
-- M2291-02 OV_h_min (Gl. 17)
update public.equations set verification_status='verified_against_standard', verification_quote='Der minimale Sauerstoffbedarf auf Anlagen ohne einen signifikanten, auch in den Nachtstunden zufließenden Frachtanteil ergibt sich vereinfacht über den Ansatz der endogenen Atmung nach Arbeitsblatt DWA-A 131:2016 Gleichung (63): | O V_{\mathrm{h}, \min }=\frac{O V_{\mathrm{d}, \mathrm{C}, \mathrm{aM}}}{\left(\frac{3,92}{t_{\mathrm{TS}} \cdot 1,072^{\left(T_{\mathrm{w}}-15\right)}}+1,66\right) \cdot 24} \quad\left(\mathrm{~kg} / \mathrm{h} \mathrm{O}_{2}\right) \tag{16} | mit $T_{\mathrm{W}}$ als der Temperatur im Jahresmittel sowie mit $t_{\mathrm{TS}}$ als dem für diesen Lastfall ermittelten Schlammalter. — printed p.35', verification_note='md-verified 2026-09-07 (§4.3.1 Gl. (16), printed p.35) [VC] — status raised from verified_via_cross_reference', verified_at=now() where id='8bb44beb-bb59-4351-8c98-b3d49b5905a6' and verification_status <> 'verified_against_standard';
-- M2291-02 OV_h_min_ind (Gl. 18)
update public.equations set verification_quote='Bei Anlagen mit einem signifikanten, auch in den Nachtstunden zufließenden Frachtanteil, z. B. durch Industrieabwasser, sollte der minimale Sauerstoffbedarf für die belastungsschwache Jahreszeit berechnet werden, wobei analog zur Ermittlung des maximalen Sauerstoffbedarfs Minimumfaktoren für den Frachtanteil in den Nachtstunden entweder messtechnisch ermittelt oder näherungsweise abgeschätzt werden sollten: | O V_{\mathrm{h}, \min }=\frac{f_{\mathrm{C}, \min } \cdot\left(O V_{\mathrm{d}, \mathrm{C}, \min }-O V_{\mathrm{d}, \mathrm{D}, \min }\right)+f_{\mathrm{N}, \min } \cdot O V_{\mathrm{d}, \mathrm{~N}, \min }}{24} \quad\left(\mathrm{~kg} / \mathrm{h} \mathrm{O}_{2}\right) \tag{17} — printed p.35', verification_note='md-verified 2026-09-07 (§4.3.1 Gl. (17), printed p.35) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='117e1201-e18e-4908-9026-582ed4419649' and verification_quote is null;
-- M2291-02 OV_h_max_Prog (Gl. 19)
update public.equations set verification_quote='\section*{I Lastfall 4: Sauerstoffbedarfswerte für den Prognose- und gegebenenfalls Revisions-Zustand} | Zusätzlich sind die oben genannten Kennwerte des Sauerstoffbedarfs auch für den PrognoseZustand bzw. die planerisch zu berücksichtigenden Revisionszustände zu ermitteln. | O V_{\mathrm{h}, \text { max }}=\frac{f_{\mathrm{C}} \cdot\left(O V_{\mathrm{d}, \mathrm{C}, \text { max }}-O V_{\mathrm{d}, \mathrm{D}, \text { max }}\right)+f_{\mathrm{N}} \cdot O V_{\mathrm{d}, \mathrm{~N}, \text { max }}}{24} \quad\left(\mathrm{~kg} / \mathrm{h} \mathrm{O}_{2}\right) \tag{15} — printed p.35, 34', verification_note='md-verified 2026-09-07 (§4.3.1 Lastfall 4 mit Gl. (15), printed p.35, 34) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='e2b8b3e5-d9c1-437e-8d7f-f5cc829bdd01' and verification_quote is null;
-- M2291-02 f_int (Gl. 20)
update public.equations set verification_quote='Bei intermittierender Belüftung sind die belüftungsfreien Zeiten über einen Erhöhungsfaktor ( $f_{\text {int }}$ ) entsprechend zu berücksichtigen: | f_{\mathrm{int}}=\frac{1}{1-V_{\mathrm{D}} / V_{\mathrm{BB}}} \tag{18} — printed p.36', verification_note='md-verified 2026-09-07 (§4.3.1 Gl. (18), printed p.36) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='6de0ad65-712a-4de8-8ae2-c64c77487663' and verification_quote is null;
-- M2291-02 f_SBR (Gl. 21)
update public.equations set verification_status='verified_against_standard', verification_quote='Ebenso ist bei SBR-Anlagen der Sauerstoffbedarf OV zusätzlich auf die Reaktionszeiten (biologische Behandlungszeit, Dauer der Reaktionsphase) nach Merkblatt DWA-M 210 umzurechnen: | f_{\mathrm{SBR}}=\frac{24}{m_{\mathrm{Z}} \cdot t_{\mathrm{R}}} \tag{-} — printed p.36', verification_note='md-verified 2026-09-07 (§4.3.1, printed p.36) [VC] — status raised from verified_via_cross_reference', verified_at=now() where id='2a838234-9fda-40b9-93e3-d2eb078cc1f1' and verification_status <> 'verified_against_standard';
-- M2291-03 beta_alpha (Gl. 11)
update public.equations set verification_status='verified_against_standard', verification_quote='In kommunalen Abwässern geht der $\beta_{\alpha}$-Wert gegen 1,0 und ist deshalb vernachlässigbar. Überschlägig kann man für kommunale Abwässer mit erheblichem Meerwasseranteil oder industrielle Abwässer den $\beta_{\alpha}$-Wert mithilfe des Gesamtgehalts an Salzen in Abwasser, $S_{\text {TDS }, \alpha}$ (g/l), berechnen (Merkblatt DWA-M 209:2007): | \beta_{\alpha}=1,00-0,01 \cdot S_{\mathrm{TDS}, \alpha} — printed p.15', verification_note='md-verified 2026-09-07 (§3.2.11, printed p.15) [VC] — status raised from verified_via_cross_reference', verified_at=now() where id='4d08d535-beec-4a75-8f1f-bc4abf9b849c' and verification_status <> 'verified_against_standard';
-- M2291-03 beta_St (Gl. 12)
update public.equations set verification_status='verified_against_standard', verification_quote='Für die Bemessung von Belüftungssystemen ist es zudem erforderlich, den Salzgehalt der Betriebsbedingungen auf den Salzgehalt unter Reinwasserbedingungen umzurechnen. Es gilt dann in Abhängigkeit des Gesamtgehalts an Salzen in Reinwasser, $S_{\text {TDS }, \mathrm{St}}(\mathrm{g} / \mathrm{l})$ : | \beta_{\mathrm{St}}=1,00-0,01 \cdot \mathrm{~S}_{\mathrm{TDS}, \mathrm{St}} \tag{-} — printed p.15', verification_note='md-verified 2026-09-07 (§3.2.11, printed p.15) [VC] — status raised from verified_via_cross_reference', verified_at=now() where id='460b0aab-2d3c-481e-b3cc-c71c06b13170' and verification_status <> 'verified_against_standard';
-- M2291-03 f_S_alpha (Gl. 13)
update public.equations set verification_quote='In kommunalem Abwasser mit geringen Salzgehalten ist der $f_{\mathrm{S}, \alpha}$ von untergeordneter Bedeutung und geht gegen 1,0. Ansonsten gilt: | f_{\mathrm{S}, \alpha}=1,00+0,08 \cdot \mathrm{~S}_{\mathrm{TDS}, \alpha} \tag{-} — printed p.15', verification_note='md-verified 2026-09-07 (§3.2.12, printed p.15) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='726323c7-e287-4ea6-9af8-4ef21fbd4a10' and verification_quote is null;
-- M2291-03 f_S_St (Gl. 14)
update public.equations set verification_quote='Für die Bemessung von Belüftungssystemen ist es zudem erforderlich, den Salzgehalt der Betriebsbedingungen auf den Salzgehalt unter Reinwasserbedingungen umzurechnen. Es gilt dann in Abhängigkeit des Gesamtgehalts an Salzen in Reinwasser, $\mathrm{S}_{\text {TDS }, \mathrm{St}}(\mathrm{g} / \mathrm{I})$ : | f_{\mathrm{S}, \mathrm{St}}=1,00+0,08 \cdot \mathrm{~S}_{\mathrm{TDS}, \mathrm{St}} \tag{13} — printed p.15', verification_note='md-verified 2026-09-07 (§3.2.12 Gl. (13), printed p.15) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='f8e43fce-5679-4241-a1df-515d92c9efb1' and verification_quote is null;
-- M2291-03 C_S_T (Gl. 31)
update public.equations set verification_quote='3.3 Abkürzungen und Symbole | \hline $C_{\mathrm{S}, \mathrm{T}}$ & mg/l & Sauerstoffsättigungskonzentration bei $T_{\mathrm{W}}\left({ }^{\circ} \mathrm{C}\right)$ : $$ \frac{2.234,34}{\left(T_{\mathrm{w}}+45,93\right)^{1,31403}} $$ \\ — printed p.16-22', verification_note='md-verified 2026-09-07 (§3.3, printed p.16-22) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='f230d2c6-c75f-4d8d-a1db-d03fdddcbd6c' and verification_quote is null;
-- M2291-03 kLa20 (Gl. 7)
update public.equations set verification_quote='Der Belüftungskoeffizient $k_{\mathrm{L}} a_{\mathrm{T}}$ in $\mathrm{h}^{-1}$ (bzw. $1 / \mathrm{h}$ ) ist der Kennwert für die in einem bestimmten Becken auf eine bestimmte Leistung eingestellte Belüftungseinrichtung. Er wird aus dem Sauerstoffzufuhrversuch bei der Wassertemperatur im Belebungsbecken $T_{\mathrm{W}}\left({ }^{\circ} \mathrm{C}\right)$ errechnet. Bei gleicher Belüftungseinstellung steigt $k_{\mathrm{L}} a_{\mathrm{T}}$ (bzw. $\alpha k_{\mathrm{L}} a_{\mathrm{T}}$ ) mit steigender Temperatur. Es gilt nach DIN EN 12255-15:2004: | k_{\mathrm{L}} a_{20}=k_{\mathrm{L}} a_{\mathrm{T}} \cdot 1,024^{\left(20-T_{\mathrm{W}}\right)} \tag{7} — printed p.14', verification_note='md-verified 2026-09-07 (§3.2.7 Gl. (7), printed p.14) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='2b23b131-69e2-4d80-ad74-12e62b7632f4' and verification_quote is null;
-- M2291-03 alpha (Gl. 8)
update public.equations set verification_quote='Der $\alpha$-Wert ist ein empirischer Faktor, der als Verhältnis der Belüftungskoeffizienten unter Betriebsund Reinwasserbedingungen definiert ist: | \alpha=\frac{k_{\mathrm{L}} a_{20} \text { in belebtem Schlamm }}{k_{\mathrm{L}} a_{20} \text { in Reinwasser }} \tag{8} — printed p.14', verification_note='md-verified 2026-09-07 (§3.2.8 Gl. (8), printed p.14) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='e9c3427a-adde-4715-8d19-1e7c3c10c918' and verification_quote is null;
-- M2291-03 SOTR_def (Gl. SOTRdef)
update public.equations set verification_quote='SOTR (Standard Oxygen Transfer Rate) in $\mathrm{kg} / \mathrm{h}$ ist der Massenstrom an Sauerstoff, der in einem repräsentativen Zeitraum im stationären Zustand von einer Belüftungseinrichtung beim Sauerstoffgehalt von $C=0 \mathrm{mg} / \mathrm{l}$, bei einer Wassertemperatur von $T_{\mathrm{W}}=20^{\circ} \mathrm{C}$ und atmosphärischem Normaldruck ( $p_{\mathrm{N}}=1.013 \mathrm{hPa}$ ) in einem mit Reinwasser gefüllten Becken bestimmter Größe ( $V$ in $\mathrm{m}^{3}$ ) gelöst wird. | \text { SOTR }=\frac{V \cdot f_{\mathrm{S}, \mathrm{St}} \cdot k_{\mathrm{L}} a_{20} \cdot \beta_{\mathrm{St}} \cdot C_{\mathrm{S}, 20}}{1.000} \quad(\mathrm{~kg} / \mathrm{h}) \tag{1} — printed p.12', verification_note='md-verified 2026-09-07 (§3.2.2 Gl. (1), printed p.12) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='45bb1c58-6ade-49fc-bee8-61f7c4dca09e' and verification_quote is null;
-- M2291-04 a_ges (Gl. 10)
update public.equations set verification_quote='\caption{Tabelle A.2: Auslegung einer Druckluftbelüftung für die Beispielanlage A. 1 (Auslegung jeweils nur für ein Becken)} | \hline $a_{\text {ges }}$ & gesamte Abgasungsfläche & $n_{\text {Bel }} \cdot a_{\text {Bel }}$ & $\mathrm{m}^{2}$ & 80 \\ — printed p.75', verification_note='md-verified 2026-09-07 (Anhang A.1 Tabelle A.2, printed p.75) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='27c85270-d863-4096-ad19-4ec035032568' and verification_quote is null;
-- M2291-04 alphaSOTR (Gl. 2)
update public.equations set verification_quote='$\alpha$ SOTR (Standard Oxygen Transfer Rate) in $\mathrm{kg} / \mathrm{h}$ ist die Masse ( kg ) an Sauerstoff, die von einer Belüftungseinrichtung beim Sauerstoffgehalt von $C=0 \mathrm{mg} / \mathrm{l}$, bei einer Wassertemperatur von $T_{\mathrm{w}}=20^{\circ} \mathrm{C}$ und atmosphärischem Normaldruck ( $p_{\mathrm{N}}=1.013 \mathrm{hPa}$ ) in einer Stunde in einem mit belebtem Schlamm gefüllten Becken bestimmter Größe gelöst wird. Es gilt in Abhängigkeit der Salzfaktoren für den Betriebszustand $\beta_{\alpha}$ für die Sauerstoffsättigung und $f_{\mathrm{s}, \alpha}$ für den Belüftungskoeffizienten: | \alpha \text { SOTR }=\frac{V \cdot \alpha \cdot f_{\mathrm{S}, \alpha} \cdot k_{\mathrm{L}} a_{20} \cdot \beta_{\alpha} \cdot C_{\mathrm{S}, 20}}{1.000} \quad(\mathrm{~kg} / \mathrm{h}) \tag{2} — printed p.13', verification_note='md-verified 2026-09-07 (§3.2.3 Gl. (2), printed p.13) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='cd4db0b7-8c86-4a09-bd01-5fa956e99d2f' and verification_quote is null;
-- M2291-04 SOTR (Gl. 22)
update public.equations set verification_quote='Die Auslegung von Druckluftbelüftungssystemen geht von dem für die einzelnen Lastfälle ermittelten Sauerstoffbedarf aus. Hieraus wird die notwendige Sauerstoffzufuhr SOTR als maßgebliche Dimensionierungsgröße für die Bemessung der Belüftung ermittelt. | \text { SOTR }=\frac{f_{\mathrm{d}} \cdot C_{\mathrm{S}, 20}}{\alpha \cdot\left(f_{\mathrm{d}} \cdot C_{\mathrm{S}, \mathrm{~T}}-C_{\mathrm{x}}\right) \cdot \theta^{\left(T_{\mathrm{W}}-20\right)}} \cdot O V_{\mathrm{h}} \quad\left(\mathrm{~kg} / \mathrm{h} \mathrm{O}_{2}\right) \tag{20} — printed p.36', verification_note='md-verified 2026-09-07 (§4.3.2 Gl. (20), printed p.36) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='16c436d2-c736-4529-a90b-601b61786e0d' and verification_quote is null;
-- M2291-04 Q_L_N (Gl. 23)
update public.equations set verification_quote='Der Luftbedarf errechnet sich schließlich unter Verwendung der spezifischen StandardSauerstoffausnutzung zu: | Q_{\mathrm{L}, \mathrm{~N}}=\frac{1.000 \cdot \text { SOTR }}{3 \cdot \text { SSOTE } \cdot h_{\mathrm{D}}} \quad\left(\mathrm{~m}_{\mathrm{N}}^{3} / \mathrm{h}\right) \tag{23} — printed p.38', verification_note='md-verified 2026-09-07 (§4.3.2 Gl. (23), printed p.38) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='b9771787-48e1-4abf-ba6e-7027c9342b9d' and verification_quote is null;
-- M2291-04 n_Bel_erf (Gl. 29)
update public.equations set verification_quote='\caption{Tabelle A.2: Auslegung einer Druckluftbelüftung für die Beispielanlage A. 1 (Auslegung jeweils nur für ein Becken)} | \hline $n_{\text {Bel,erf }}$ & erforderliche Anzahl der Belüfterelemente & $\frac{Q_{\llcorner, \mathrm{N}}}{q_{\mathrm{L}, \mathrm{Bel}}}$ & - & \\ — printed p.75', verification_note='md-verified 2026-09-07 (Anhang A.1 Tabelle A.2, printed p.75) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='139e1eb2-0362-4dcd-95e9-9aea587bbfde' and verification_quote is null;
-- M2291-04 SAE (Gl. 3)
update public.equations set verification_quote='Die Leistungsaufnahme $P(\mathrm{~kW})$ der Belüftungseinrichtung ist gegebenenfalls einschließlich zugehöriger Mischeinrichtungen zu bestimmen, es gilt: | \text { SAE }=\frac{\text { SOTR }}{P} \quad(\mathrm{~kg} / \mathrm{kWh}) \tag{3} — printed p.13', verification_note='md-verified 2026-09-07 (§3.2.4 Gl. (3), printed p.13) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='5a5578b4-1188-4523-995c-804e2f3811ba' and verification_quote is null;
-- M2291-04 f_d (Gl. 30)
update public.equations set verification_quote='3.3 Abkürzungen und Symbole | \hline $f_{\mathrm{d}}$ & - & \begin{tabular}{l} Tiefenfaktor bei der Druckluftbelüftung: \\ $1+\frac{h_{D}}{20,7}\left(1+\frac{0,5 \cdot h_{D}}{10,33}\right)$ \\ Tiefenfaktor bei der Oberflächenbelüftung: \\ $1+\frac{h_{\mathrm{BB}}}{150}$ \end{tabular} \\ — printed p.16-22', verification_note='md-verified 2026-09-07 (§3.3, printed p.16-22) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='35563723-4d5d-41ed-bd88-c8c7a0f3877a' and verification_quote is null;
-- M2291-04 SOTR_alt (Gl. 36)
update public.equations set verification_quote='Ab einer Höhe von 600 m . ü. NN und bei Salzgehalten $S_{\text {TDS }, \alpha}<2 \mathrm{~g} / \mathrm{l}$ wird empfohlen, zusätzlich auch noch den Einfluss der Höhenlage auf die Sauerstoffsättigungskonzentration zu berücksichtigen: | \text { SOTR }=\frac{f_{\mathrm{d}} \cdot C_{\mathrm{S}, 20}}{\alpha \cdot\left(f_{\mathrm{d}} \cdot C_{\mathrm{S}, \mathrm{~T}} \cdot \frac{p_{\mathrm{atm}}}{1.013}-C_{\mathrm{x}}\right) \cdot \theta^{\left(T_{\mathrm{w}}-20\right)}} \cdot O V_{\mathrm{h}} \quad\left(\mathrm{~kg} / \mathrm{h} \mathrm{O}_{2}\right) \tag{21} — printed p.36', verification_note='md-verified 2026-09-07 (§4.3.2 Gl. (21), printed p.36) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='80467129-1929-4bdf-9227-0f8798bc978e' and verification_quote is null;
-- M2291-04 SOTR_salz (Gl. 37)
update public.equations set verification_quote='Bei Salzgehalten $S_{\text {TDS }, \alpha}>2 \mathrm{~g}$ TDS/l sollten die Einflüsse des Salzes im Abwasser auf den Sauerstoffsättigungswert ( $\beta_{\mathrm{St}}$ und $\beta_{\alpha}$ ) und auf den Belüftungskoeffizienten ( $f_{\mathrm{S}, \mathrm{St}}$ und $f_{\mathrm{S}, \alpha}$ ) berücksichtigt werden: | \text { SOTR }=\frac{f_{\mathrm{d}} \cdot \beta_{\mathrm{St}} \cdot C_{\mathrm{S}, 20} \cdot f_{\mathrm{S}, \mathrm{St}}}{\alpha \cdot f_{\mathrm{S}, \alpha} \cdot\left(f_{\mathrm{d}} \cdot \beta_{\alpha} \cdot C_{\mathrm{S}, \mathrm{~T}} \cdot \frac{p_{\mathrm{atm}}}{1.013}-C_{\mathrm{x}}\right) \cdot \theta^{\left(T_{\mathrm{W}}-20\right)}} \cdot O V_{\mathrm{h}} \quad\left(\mathrm{~kg} / \mathrm{h} \mathrm{O}_{2}\right) \tag{22} — printed p.36', verification_note='md-verified 2026-09-07 (§4.3.2 Gl. (22), printed p.36) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='1aaff78a-86d1-4249-8586-fb208114954e' and verification_quote is null;
-- M2291-04 alphaSAE (Gl. 4)
update public.equations set verification_quote='$\alpha$ SAE in kg/kWh ist die Masse an Sauerstoff (kg), die pro Kilowattstunde (kWh) einem mit belebtem Schlamm gefüllten Becken unter Standardbedingungen zugeführt wird. Die Leistungsaufnahme $P$ (kW) der Belüftungseinrichtung ist gegebenenfalls einschließlich zugehöriger Mischeinrichtungen zu bestimmen, es gilt: | \alpha S A E=\frac{\alpha S O T R}{P} \quad(\mathrm{~kg} / \mathrm{kWh}) \tag{4} — printed p.13', verification_note='md-verified 2026-09-07 (§3.2.5 Gl. (4), printed p.13) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='53681238-e4dd-4a6c-b974-f5370a0c66cd' and verification_quote is null;
-- M2291-04 SSOTE (Gl. 5)
update public.equations set verification_quote='Die spezifische Standard-Sauerstoffausnutzung SSOTE (Specific Standard Oxygen Transfer Efficiency) in \%/m ist ein Bezugswert, der zum Vergleich von Druckluft-Belüftungseinrichtungen benutzt wird. Es gilt mit $Q_{\mathrm{L}, \mathrm{N}}\left(\mathrm{m}^{3} / \mathrm{h}\right)$, angesaugter trockener Luft bei $T_{\mathrm{N}}=0^{\circ} \mathrm{C}$ und $p_{\mathrm{N}}=1.013 \mathrm{hPa}$ und des Sauerstoffgehalts der Luft von $300 \mathrm{~g} / \mathrm{m}^{3}\left(0,2095 \mathrm{~m}^{3} \mathrm{O}_{2} / \mathrm{m}^{3} \mathrm{Luft} \cdot 1.429 \mathrm{~g} \mathrm{O}_{2} / \mathrm{m}^{3}\right.$ Luft $)$ für die Sauerstoffausnutzung: | \text { SSOTE }=\frac{100 \cdot \text { SOTR }}{h_{\mathrm{D}} \cdot\left(Q_{\mathrm{L}, \mathrm{~N}} \cdot 0,3\right)} \quad(\% / \mathrm{m}) \tag{5} — printed p.13', verification_note='md-verified 2026-09-07 (§3.2.6 Gl. (5), printed p.13) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='505f46b1-7144-44da-a8a1-34e9c62e3a4c' and verification_quote is null;
-- M2291-04 SSOTR (Gl. 6)
update public.equations set verification_quote='Die spezifische Standard-Sauerstoffzufuhr SSOTR (Specific Standard Oxygen Transfer Rate) in $\mathrm{g} /\left(\mathrm{m}_{\mathrm{N}}^{3} \cdot \mathrm{~m}\right)$ ist ein in Deutschland gebräuchlicher Bezugswert, für den die obigen Vorgaben gelten: | \text { SSOTR }=\frac{\text { SOTR }}{h_{\mathrm{D}} \cdot Q_{\mathrm{L}, \mathrm{~N}}} \cdot 1.000 \quad\left(\mathrm{~g} /\left(\mathrm{m}_{\mathrm{N}}^{3} \cdot \mathrm{~m}\right)\right) \tag{6} — printed p.13', verification_note='md-verified 2026-09-07 (§3.2.6 Gl. (6), printed p.13) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='c81998f0-ae38-40af-989b-cb49439a9e6f' and verification_quote is null;
-- M2291-04 BD (Gl. 9)
update public.equations set verification_quote='Die Belegungsdichte ( $B D$ ) ergibt sich als Verhältnis der abgasenden Fläche der Belüfter ( $n_{\text {Bel }} \cdot a_{\text {Bel }}$ ) durch die Beckengrundfläche ( $A_{\mathrm{BB}}$ ). | B D=\frac{n_{\mathrm{Bel}} \cdot a_{\mathrm{Bel}}}{A_{\mathrm{BB}}} — printed p.14', verification_note='md-verified 2026-09-07 (§3.2.9, printed p.14) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='cd3b95a5-3c61-4f9c-8654-fe11e4208110' and verification_quote is null;
-- M2291-05 p_atm (Gl. 25)
update public.equations set verification_quote='Für eine genaue Ermittlung der erforderlichen Luftmenge ist zunächst der Luftdruck ( $p_{\text {atm }}$ ) in Abhängigkeit von der geodätischen Höhenlage der Anlage zu ermitteln: | p_{\text {atm }}=1.013,25 \cdot\left(\frac{288-0,0065 \cdot h_{\text {geo }}}{288}\right)^{5,255} \quad \text { (hPa) } \tag{26} — printed p.38', verification_note='md-verified 2026-09-07 (§4.3.2 Gl. (26), printed p.38) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='3d9d0643-e2c8-407d-9548-dbd0435c7358' and verification_quote is null;
-- M2291-05 p_1_abs (Gl. 26)
update public.equations set verification_quote='Abzüglich der Verluste auf der Saugseite ( z . B. Luftfilter, Saugleitung: $\Delta p_{1}$ ) errechnet sich der Ansaugdruck ( $p_{1, \text { abs }}$ ) zu: | p_{1, \text { abs }}=p_{\text {atm }}-\Delta p_{1} \quad \text { (hPa) } \tag{27} — printed p.38', verification_note='md-verified 2026-09-07 (§4.3.2 Gl. (27), printed p.38) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='c1e5816c-202a-452d-b72a-0ce2c5254e91' and verification_quote is null;
-- M2291-05 rho_1 (Gl. 27)
update public.equations set verification_quote='Die Dichte im Ansaugzustand ( $\rho_{1}$ ) lässt sich wie folgt ermitteln: | \rho_{1}=\rho_{\mathrm{N}} \cdot \frac{T_{\mathrm{N}}}{T_{\mathrm{N}}+T_{\mathrm{L}, 1}} \cdot \frac{p_{1, \mathrm{abs}}-\varphi \cdot p_{\mathrm{S}}}{p_{\mathrm{N}}}+\varphi \cdot \rho_{\mathrm{S}} \quad\left(\mathrm{~kg} / \mathrm{m}^{3}\right) \tag{28} — printed p.38', verification_note='md-verified 2026-09-07 (§4.3.2 Gl. (28), printed p.38) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='6c355a8c-c32d-4082-887d-211b2e51ec3a' and verification_quote is null;
-- M2291-05 Q_1 (Gl. 28)
update public.equations set verification_quote='Damit ergibt sich der Ansaugvolumenstrom ( $Q_{1}$ ) schließlich zu: | Q_{1}=\frac{T_{\mathrm{N}}+T_{\mathrm{L}, 1}}{T_{\mathrm{N}}} \cdot \frac{p_{\mathrm{N}}}{p_{1, \mathrm{abs}}-\varphi \cdot p_{\mathrm{S}}} \cdot Q_{\mathrm{L}, \mathrm{~N}} \quad\left(\mathrm{~m}^{3} / \mathrm{min}\right) \tag{29} — printed p.38', verification_note='md-verified 2026-09-07 (§4.3.2 Gl. (29), printed p.38) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='2db59989-9bdd-4a0e-9276-24f19caa6e67' and verification_quote is null;
-- M2291-05 P_th (Gl. 32)
update public.equations set verification_quote='3.3 Abkürzungen und Symbole | \hline $P_{\mathrm{th}}$ & kW & Verdichterleistung $\frac{Q_{0} \cdot \Delta p}{600}$ \\ — printed p.16-22', verification_note='md-verified 2026-09-07 (§3.3, printed p.16-22) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='905b5548-2eb7-43f5-a95b-7d75cfb26aaf' and verification_quote is null;
-- M2291-05 P_K (Gl. 33)
update public.equations set verification_quote='3.3 Abkürzungen und Symbole | \hline $P_{\mathrm{K}}$ & kW & Kupplungsleistung $$ \frac{Q_{0} \cdot \Delta p}{600}+P_{\mathrm{v}} $$ \\ — printed p.16-22', verification_note='md-verified 2026-09-07 (§3.3, printed p.16-22) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='21f30060-158d-48ce-9f50-65e6e98c4f65' and verification_quote is null;
-- M2291-05 P_N_el (Gl. 34)
update public.equations set verification_quote='3.3 Abkürzungen und Symbole | \hline $P_{\mathrm{N}}$ & kW & Netzleistung $\frac{P_{\mathrm{K}}}{\eta_{\text {ges }}}$ \\ — printed p.16-22', verification_note='md-verified 2026-09-07 (§3.3, printed p.16-22) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='889f6100-0925-4735-8b00-012ebb185460' and verification_quote is null;
-- M2291-05 delta_p_Bel (Gl. 39)
update public.equations set verification_quote='Für den Druckverlust eines Belüfterelements ( $\Delta p_{\text {Bel }}$ ) gilt in Abhängigkeit der Luftgeschwindigkeit ( $v$ ), der Dichte $(\rho)$ und der Summe der Druckverlustbeiwerte $(\Sigma \zeta=$ konstant): | \Delta p_{\text {Bel }}=\sum \zeta \cdot \rho \cdot \frac{v^{2}}{2} \tag{C.1} — printed p.95', verification_note='md-verified 2026-09-07 (Anhang C Gl. (C.1), printed p.95) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='4b385bc0-3870-4916-a5c1-25d6faca11d9' and verification_quote is null;
-- M2291-05 Q_L_B (Gl. 40)
update public.equations set verification_quote='Für die Umrechnung des Luftvolumenstroms für verschiedene Zustandsgrößen gilt unter der Annahme von Luft als ideales Gas: | Q_{\mathrm{L}, \mathrm{~B}}=Q_{\mathrm{L}, \mathrm{~N}} \cdot \frac{T_{\mathrm{B}} \cdot p_{\mathrm{N}}}{T_{\mathrm{N}} \cdot p_{\mathrm{B}}} \tag{C.2} — printed p.95', verification_note='md-verified 2026-09-07 (Anhang C Gl. (C.2), printed p.95) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='82fdf238-5c6c-4b2d-82b5-5ae2b81e2a3c' and verification_quote is null;
-- M2291-05 rho_B (Gl. 41)
update public.equations set verification_quote='Für die Umrechnung der Dichte für verschiedene Zustandsgrößen gilt: | \rho_{\mathrm{B}}=\rho_{\mathrm{N}} \cdot \frac{T_{\mathrm{N}} \cdot p_{\mathrm{B}}}{T_{\mathrm{B}} \cdot p_{\mathrm{N}}} \tag{C.3} — printed p.95', verification_note='md-verified 2026-09-07 (Anhang C Gl. (C.3), printed p.95) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='e5c1e110-15fd-4d53-8b07-e7d149b206db' and verification_quote is null;
-- M2291-05 delta_p_Bel_B (Gl. 42)
update public.equations set verification_quote='Berechnet man nun die Druckverluste bei verschiedenen Zustandsgrößen der Luft laber konstantem Massenstrom) unter der Annahme, dass die Summe der Druckverlustbeiwerte ( $\boldsymbol{\zeta}$ ) konstant ist, erhält man nach Umformung: | \Delta p_{\mathrm{Bel}, \mathrm{~B}}=\Delta p_{\mathrm{Bel}, \mathrm{~N}} \cdot \frac{T_{\mathrm{B}} \cdot p_{\mathrm{N}}}{T_{\mathrm{N}} \cdot p_{\mathrm{B}}} \tag{C.4} — printed p.95', verification_note='md-verified 2026-09-07 (Anhang C Gl. (C.4), printed p.95) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='bf2fde65-abe1-4427-8d59-90bfacf0b2d4' and verification_quote is null;
