-- M2291-05 Q_1_tr (Gl. Q1tr)
update public.equations set verification_quote='Zur Auslegung der Gebläse ist eine Umrechnung des für den Normzustand ermittelten Luftbedarfs in den Volumenstrom im Ansaugzustand unter Berücksichtigung von Temperatur, Feuchte und Höhenlage der Anlage erforderlich. Näherungsweise kann der erforderliche Volumenstrom für trockene Luft aber auch wie folgt errechnet werden: | Q_{1}=\frac{p_{\mathrm{N}} \cdot\left(T_{\mathrm{L}, 1}+T_{\mathrm{N}}\right)}{p_{1, \mathrm{abs}} \cdot T_{\mathrm{N}}} \cdot Q_{\mathrm{L}, \mathrm{~N}} \quad\left(\mathrm{~m}^{3} / \mathrm{h}\right) \tag{25} — printed p.38', verification_note='md-verified 2026-09-07 (§4.3.2 Gl. (25), printed p.38) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='7c6baa0f-625a-4db4-b0a7-2845c9c28ca5' and verification_quote is null;
